"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["7451"],{74910(e){e.exports=JSON.parse('{"id":"FIN-1171","slug":"market-manipulation","term":"Market Manipulation","also_known_as":[],"difficulty":"Advanced","definition":"Market manipulation is deliberately interfering with the free and fair operation of a market to create artificial prices or a false impression of supply, demand or trading activity.","explanation":["Markets rely on prices reflecting genuine supply and demand. Manipulation distorts this, misleading other investors and damaging trust. It is illegal in most countries.","Common forms include pump-and-dump schemes; spoofing, placing large orders with no intention of executing them to mislead others, then cancelling them; wash trading, buying and selling the same asset to create the appearance of activity; spreading false information; and cornering a market, gaining enough control of an asset\'s supply to dictate its price.","For example, a trader who places large buy orders to make a share look in demand, sells shares at the resulting higher price, then cancels the buy orders, is engaged in spoofing.","Regulators and exchanges monitor trading for unusual patterns using surveillance technology. Penalties include fines, bans from trading and prison sentences. Market manipulation rules apply to shares, bonds, derivatives, commodities and, increasingly, cryptocurrencies, where trading can be less regulated and manipulation harder to detect."],"note":"","total":1725,"prev":{"slug":"market-maker","term":"Market Maker"},"next":{"slug":"market-neutral-strategy","term":"Market-Neutral Strategy"}}')}}]);